package io.github.rebrowser.data;
import static org.junit.Assert.*;
import java.util.*;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import org.junit.Test;
import io.github.rebrowser.browser.BookmarkStore;
import io.github.rebrowser.bootstrap.ComponentGate;
/** Actual HOST filesystem/JCA/CAS over the canonical favorites family; no Android/source grant. */
public final class UrlFavoritesStoreTest {
 private void seed(BrowserMetadataStoreTest.F f)throws Exception{try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){assertEquals(PrivateRecordStore.Kind.MISSING,view.kind());f.bookmarks.compareAndWrite(view,new BookmarkStore.Snapshot(0,Collections.emptyList()),f.permit);}}
 @Test public void flatAddEditRemoveActuallyRoundTripEncryptedRecord()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);String id;try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){f.bookmarks.compareAndWrite(view,view.value(f.permit).add("private-favorite","https://www.baidu.com/"),f.permit);}try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){BookmarkStore.Node node=view.value(f.permit).nodes().get(0);id=node.id();f.bookmarks.compareAndWrite(view,view.value(f.permit).editExact(id,node.url(),"edited","https://cn.bing.com/#saved"),f.permit);}try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){assertEquals("https://cn.bing.com/#saved",view.value(f.permit).require(id).url());f.bookmarks.compareAndWrite(view,view.value(f.permit).removeExact(id,"https://cn.bing.com/#saved"),f.permit);}try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){assertTrue(view.value(f.permit).nodes().isEmpty());}String bytes=new String(Files.readAllBytes(f.root.resolve(f.ref(OwnedDataCatalog.Family.BOOKMARKS).opaqueRef())),java.nio.charset.StandardCharsets.ISO_8859_1);assertFalse(bytes.contains("private-favorite"));}}
 @Test public void duplicateFavoriteIdentityDoesNotCreateNewSnapshotOrLoseFullUrl()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){BookmarkStore.Snapshot snapshot=view.value(f.permit).add("x","https://www.baidu.com/#first");assertSame(snapshot,snapshot.add("other","https://www.baidu.com/#second"));assertEquals("https://www.baidu.com/#first",snapshot.nodes().get(0).url());f.bookmarks.compareAndWrite(view,snapshot,f.permit);}try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){assertEquals(1,view.value(f.permit).nodes().size());}}}
 @Test public void correctedFlatSubsetKeepsActualInitialEmptyBytesCompatible(){byte[] previous=new NativeRecordCodec.Writer("RBBOOK01",100).nonnegative(0).u16(0).finish();assertArrayEquals(previous,BookmarkStore.CODEC.encode(BookmarkStore.CODEC.decode(ByteBuffer.wrap(previous))));}
 @Test public void existingFavoritesDoNotDefaultAfterSourceFence()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.source.set(ComponentGate.SourceView.untrusted(ComponentGate.SourceState.LOCKED));assertThrows(SecurityException.class,()->f.bookmarks.read(f.permit));}}
 @Test public void sameSnapshotOrSkippedMetadataRevisionCannotBeWritten()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);try(OwnedDataCatalog.View<BookmarkStore.Snapshot> view=f.bookmarks.read(f.permit)){BookmarkStore.Snapshot base=view.value(f.permit);assertThrows(IllegalArgumentException.class,()->f.bookmarks.compareAndWrite(view,base,f.permit));assertThrows(IllegalArgumentException.class,()->f.bookmarks.compareAndWrite(view,base.add("a","https://www.baidu.com/").add("b","https://cn.bing.com/"),f.permit));}}}
}
